src:
board [
  page [
    textbox id "heading" text "Workshop agenda" font-size LARGE {}
    group [
      section [
        textbox id "goal" text "Agree on the release scope" {}
      ] id "goals" name "Goals" {}
      section [
        sticky id "scope" text "Discuss scope" {}
        sticky id "risk" text "Review risks" {}
        sticky id "owner" text "Assign owners" {}
      ] id "topics" name "Topics" layout GRID columns 2 {}
    ] id "agenda-panels" layout ROW {}
  ] id "agenda" name "Agenda" layout COLUMN {}
] layout-profile FIGJAM_V1 {}..

board [ page [
  sticky id "s" text "" fill "#fc0" opacity 50 font-size LARGE {}
  shape id "sh" text "Shape" kind ENG_DATABASE fill "white" stroke "#112233" stroke-width THICK opacity 80 font-size SMALL {}
  textbox id "t" text "Line one\nLine two" color "gray" font-size HUGE {}
  connector id "c" from "s" to "t" label "" stroke "red" stroke-width THICK opacity 40 font-size MEDIUM line-style DASHED from-cap CIRCLE_FILLED to-cap TRIANGLE_FILLED {}
] id "p1" name "Page" background "#eeeeee" layout GRID columns 2 {} ] title "All" show-page-tabs true show-page-menu true layout-profile FIGJAM_V1 {}..

board [ page [
  sticky id "d" text "Loose idea" {}
  shape id "a" text "Start" kind ELLIPSE {}
  shape id "b" text "Build" {}
  shape id "c" text "Ship" kind ROUNDED_RECTANGLE {}
  sticky id "e" text "Another loose idea" {}
  connector id "a-b" from "a" to "b" {}
  connector id "b-c" from "b" to "c" {}
] id "p1" name "Mixed" {} ] {}..

board [ page [
  section [ sticky id "a" text "A" {} ] id "left" name "Left" before ["right"] {}
  section [ sticky id "b" text "B" {} ] id "right" name "Right" {}
  connector id "ab" from "a" to "b" {}
] id "p1" name "Page" layout FLOW direction DOWN {} ] {}..

board [
  page [
    sticky id "first" text "First page" {}
  ] id "week-1" name "Notes" {}
  page [
    sticky id "second" text "Second page" {}
    textbox id "caption" text "A textbox wide enough to wrap onto a second line in FigJam" {}
  ] id "week-2" name "Notes" layout COLUMN {}
] {}..

board [ page [
  section [ ] id "ideas" name "Ideas" {}
  group [ ] id "spare" {}
] id "p1" name "Template" layout ROW {}
page [ ] id "p2" name "Empty page" {} ] title "Workshop" {}..

board [ page [
  group [ sticky id "b" text "Second, declared first" {} ] id "g2" {}
  group [ sticky id "a" text "First" {} ] id "g1" {}
  connector id "a-b" from "a" to "b" label "then" {}
] id "p1" name "Lifted" layout FLOW {} ] {}..

board [
  page [
    shape id "fetch" text "Fetch data" kind ROUNDED_RECTANGLE before ["valid"] {}
    shape id "valid" text "Valid?" kind DIAMOND before ["save" "error"] {}
    shape id "save" text "Save result" kind ROUNDED_RECTANGLE {}
    shape id "error" text "Report error" kind ROUNDED_RECTANGLE {}
    connector id "fetch-valid" from "fetch" to "valid" {}
    connector id "valid-save" from "valid" to "save" label "Yes" {}
    connector id "valid-error" from "valid" to "error" label "No" {}
    connector id "retry" from "error" to "fetch" label "Retry" line-style DASHED {}
  ] id "processing" name "Processing" layout FLOW direction RIGHT {}
] layout-profile FIGJAM_V1 {}..

board [ page [
  shape id "one" text "One" before ["two"] {}
  shape id "two" text "Two" {}
  section [
    sticky id "low" text "Bottom" before ["high"] {}
    sticky id "high" text "Top" {}
  ] id "climb" name "Climb" layout FLOW direction UP {}
] id "p1" name "Reversed" layout FLOW direction LEFT {} ] {}..

board [
  page [ sticky id "a" text "A" {} connector id "ab" from "a" to "b" {} ] id "p1" name "One" {}
  page [ sticky id "b" text "B" {} ] id "p2" name "Two" {}
] {}..

board [
  page [ ] id "p1" name "One" {}
  page [ ] id "p2" name "Two" {}
] show-page-tabs false {}..

board [ page [
  sticky id "a" text "A" before ["b"] {}
  sticky id "b" text "B" before ["c"] {}
  sticky id "c" text "C" before ["a"] {}
] id "p1" name "Page" layout FLOW {} ] {}..

board [
  page [
    shape id "a" text "A" before ["b"] {}
    shape id "b" text "B" before ["a"] {}
  ] id "cycle" name "Invalid order" layout FLOW {}
] layout-profile FIGJAM_V1 {}..

board [ page [
  section [
    sticky id "intro" text "Intro" {}
  ] id "task-section" name "task" {}
  shape id "task" text "Task" {}
  connector id "intro-task" from "intro" to "task" label "next" {}
  connector id "task-loop" from "task" to "task" label "retry" from-cap CIRCLE_FILLED to-cap TRIANGLE_FILLED {}
] id "p1" name "Collision" layout ROW {} ] {}..

board [
  page [
    section [
      textbox id "estado-neda" text "Estado declarado: proposta independente de interesse público; não apresentada como instituição legalmente registada, aprovada ou endossada." font-size LARGE color "black" {}
      textbox id "regra-leitura" text "Leitura: Proposta = acção pretendida; Condição = requisito antes de avançar; Resultado = só após medição." color "gray" {}
      group [
        sticky id "missao-neda" text "Proposta — Promover inteligência artificial responsável que beneficie as pessoas, proteja direitos e apoie o desenvolvimento sustentável, começando no Sumbe, Angola." fill "#dbeafe" {}
        shape id "piloto-central" text "Piloto administrativo numa unidade de saúde" kind ROUNDED_RECTANGLE fill "#dcfce7" {}
        shape id "portas-centrais" text "Condições críticas cumpridas?" kind DIAMOND fill "#fef3c7" {}
        shape id "decisao-escala" text "Escalar após medir?" kind DIAMOND fill "#ede9fe" {}
      ] id "fluxo-central" layout FLOW direction RIGHT {}
    ] id "visao-central" name "Missão, piloto e decisão" layout COLUMN fill "#f8fafc" {}
    section [
      sticky id "piloto-ambito" text "Proposta — Apoio à marcação administrativa e à gestão de filas numa única unidade de saúde. Todo o poder de decisão permanece com os profissionais humanos." fill "#dcfce7" {}
      sticky id "piloto-funcoes" text "Funções: registo de marcações; consulta do estado da fila; lembretes apenas com consentimento e canal disponível; relatórios operacionais simples." fill "#ecfdf5" {}
      sticky id "piloto-limites" text "Fora do âmbito: diagnóstico; triagem de urgência clínica; prescrições; priorização de pacientes por IA; decisões clínicas autónomas." fill "#fee2e2" {}
    ] id "primeiro-piloto" name "Primeiro piloto recomendado" layout COLUMN fill "#f0fdf4" {}
    section [
      shape id "autorizacao-escrita" text "Autorização escrita obtida?" kind DIAMOND fill "#fef3c7" {}
      sticky id "autoridades-condicao" text "Condição — Obter autorização escrita da unidade de saúde e das autoridades de saúde competentes. Sem autorização, não iniciar." fill "#fef3c7" {}
      sticky id "fluxo-existente" text "Condição — Avaliar o fluxo de trabalho actual, necessidades reais, capacidades da equipa e sistemas já existentes." fill "#fff7ed" {}
      sticky id "compatibilidade-dhis2" text "Condição — Assegurar compatibilidade com o ecossistema nacional de informação sanitária DHIS2 de Angola; não criar um sistema paralelo." fill "#fff7ed" {}
    ] id "dependencias-criticas" name "Dependências e portas críticas" layout COLUMN fill "#fffbeb" {}
    section [
      shape id "etapa-consulta" text "Consulta e linha de base" kind ROUNDED_RECTANGLE fill "#dbeafe" {}
      shape id "etapa-processos" text "Mapear processos" kind ROUNDED_RECTANGLE fill "#dbeafe" {}
      shape id "etapa-revisao" text "Revisão legal e de segurança" kind ROUNDED_RECTANGLE fill "#fef3c7" {}
      shape id "etapa-prototipo" text "Protótipo com dados mínimos" kind ROUNDED_RECTANGLE fill "#fef3c7" {}
      shape id "etapa-formacao" text "Formar a equipa" kind ROUNDED_RECTANGLE fill "#dcfce7" {}
      shape id "etapa-piloto" text "Piloto limitado" kind ROUNDED_RECTANGLE fill "#dcfce7" {}
      shape id "etapa-avaliacao" text "Avaliação independente" kind ROUNDED_RECTANGLE fill "#ede9fe" {}
      shape id "etapa-escala" text "Escala após evidência e aprovação" kind ROUNDED_RECTANGLE fill "#ede9fe" {}
    ] id "etapas-implementacao" name "Etapas de implementação" layout GRID columns 2 fill "#f8fafc" {}
    section [
      sticky id "indicadores-fluxo" text "Medir antes e depois, sem valores-alvo pré-preenchidos: tempo de espera; faltas às marcações; erros de registo; tempo da equipa dedicado à administração." fill "#e0f2fe" {}
      sticky id "indicadores-experiencia" text "Medir antes e depois: satisfação dos utilizadores; disponibilidade do sistema; reclamações; incidentes de privacidade e segurança." fill "#e0f2fe" {}
      sticky id "indicadores-regra" text "Resultado — Documentar método, fonte, período e limitações de cada indicador. Comparar a linha de base com o piloto antes de decidir sobre escala." fill "#f3e8ff" {}
    ] id "indicadores-sucesso" name "Indicadores de sucesso" layout COLUMN fill "#f0f9ff" {}
    section [
      sticky id "risco-acesso" text "Sem acesso institucional — Não iniciar." fill "#fee2e2" {}
      sticky id "risco-dados" text "Exposição de dados de saúde — Minimização de dados, acesso por funções, encriptação, limites de retenção, plano de incidentes e revisão legal." fill "#fee2e2" {}
      sticky id "risco-conectividade" text "Conectividade instável — Alternativa offline ou de baixa largura de banda." fill "#fff7ed" {}
      sticky id "risco-resistencia" text "Resistência da equipa — Co-criação e formação." fill "#fff7ed" {}
      sticky id "risco-duplicacao" text "Sistemas duplicados — Integrar com o existente ou parar." fill "#fef3c7" {}
      sticky id "risco-exclusao" text "Exclusão de pessoas sem telefone — Manter atendimento presencial e opção em papel." fill "#fef3c7" {}
      sticky id "risco-fornecedor" text "Dependência de fornecedor e aumento de custos — Normas abertas, portabilidade e plano de saída." fill "#ede9fe" {}
      sticky id "risco-ia" text "Erros de IA — Manter a IA fora das decisões clínicas." fill "#ede9fe" {}
    ] id "riscos-mitigacoes" name "Riscos principais e mitigação" layout GRID columns 2 fill "#fff7f7" {}
    section [
      sticky id "viabilidade-valor" text "Condição — Valor público credível e alinhamento com políticas relevantes." fill "#e0e7ff" {}
      sticky id "viabilidade-originalidade" text "Condição — Demonstrar originalidade face às iniciativas existentes, evitando duplicação." fill "#e0e7ff" {}
      sticky id "viabilidade-execucao" text "Condição — Âmbito faseado, governação multidisciplinar e resultados mensuráveis." fill "#e0e7ff" {}
      sticky id "viabilidade-integridade" text "Condição — Financiamento transparente e auditoria independente." fill "#e0e7ff" {}
      sticky id "viabilidade-parcerias" text "Não alegar parceria, aprovação ou endosso da UNESCO, União Africana, MINSA ou outras entidades até existir acordo formal." fill "#fee2e2" {}
    ] id "condicoes-viabilidade" name "Viabilidade geral da NEDA" layout GRID columns 2 fill "#eef2ff" {}
    section [
      sticky id "dominios-futuros" text "Fases posteriores propostas: educação; conectividade; agricultura; ambiente; serviços públicos; telecomunicações." fill "#f3e8ff" {}
      sticky id "dominios-regra" text "Não lançar estes domínios em simultâneo. Priorizar, testar e aprender com o primeiro piloto antes de ampliar o âmbito." fill "#ede9fe" {}
    ] id "fases-posteriores" name "Outros domínios — fases posteriores" layout COLUMN fill "#faf5ff" {}
    section [
      sticky id "salvaguardas-humanas" text "Supervisão humana; respeito pelos direitos; acessibilidade; participação comunitária." fill "#dbeafe" {}
      sticky id "salvaguardas-institucionais" text "Transparência; prestação de contas; responsabilidades e decisões documentadas." fill "#dbeafe" {}
      sticky id "salvaguardas-dados" text "Protecção de dados; cibersegurança; acesso limitado; resposta a incidentes." fill "#dbeafe" {}
    ] id "salvaguardas-governacao" name "Salvaguardas de governação" layout COLUMN fill "#eff6ff" {}
    connector id "ligacao-missao-piloto" from "missao-neda" to "piloto-central" label "primeira aplicação proposta" stroke "#2563eb" stroke-width THICK {}
    connector id "ligacao-piloto-portas" from "piloto-central" to "portas-centrais" label "só avança se" stroke "#ca8a04" stroke-width THICK {}
    connector id "ligacao-portas-decisao" from "portas-centrais" to "decisao-escala" label "evidência e aprovação" stroke "#7c3aed" stroke-width THICK {}
    connector id "ligacao-portas-autorizacao" from "portas-centrais" to "autorizacao-escrita" label "inclui autorização formal" line-style DASHED stroke "#ca8a04" {}
    connector id "ligacao-consulta-processos" from "etapa-consulta" to "etapa-processos" label "depois" {}
    connector id "ligacao-processos-revisao" from "etapa-processos" to "etapa-revisao" label "depois" {}
    connector id "ligacao-revisao-prototipo" from "etapa-revisao" to "etapa-prototipo" label "se conforme" {}
    connector id "ligacao-prototipo-formacao" from "etapa-prototipo" to "etapa-formacao" label "preparar operação" {}
    connector id "ligacao-formacao-piloto" from "etapa-formacao" to "etapa-piloto" label "iniciar limitado" {}
    connector id "ligacao-piloto-avaliacao" from "etapa-piloto" to "etapa-avaliacao" label "medir antes e depois" {}
    connector id "ligacao-avaliacao-escala" from "etapa-avaliacao" to "etapa-escala" label "só com evidência e aprovação" stroke "#7c3aed" stroke-width THICK {}
    connector id "ligacao-decisao-etapa-escala" from "decisao-escala" to "etapa-escala" label "decisão medida" line-style DASHED stroke "#7c3aed" {}
  ] id "estrategia-neda" name "Estratégia do projecto" layout GRID columns 3 background "#f8fafc" {}
] title "NEDA — Viabilidade e piloto inicial no Sumbe" show-page-tabs false {}..

board [
  page [
    section [
      sticky id "neda-status" text "Estado: iniciativa independente de interesse público proposta. Não é apresentada como instituição legalmente registada, aprovada ou endossada." fill "#e8eef7" {}
      sticky id "neda-goal" text "Objectivo central: promover IA responsável que beneficie as pessoas, proteja direitos e apoie o desenvolvimento sustentável, começando no Sumbe, Angola." fill "#d9eaf7" {}
      sticky id "neda-claims" text "Comunicação responsável: distinguir factos confirmados de acções propostas e não alegar parcerias com UNESCO, União Africana ou MINSA sem acordo formal." fill "#fff2cc" {}
    ] id "mission-section" name "Missão e estatuto da NEDA" layout COLUMN fill "white" {}
    section [
      sticky id "pilot-core" text "Primeiro piloto recomendado: apoio administrativo à marcação de consultas e à gestão de filas numa única unidade sanitária." fill "#d9ead3" {}
      sticky id "pilot-functions" text "Funções propostas: registo de marcações, estado da fila, lembretes apenas com consentimento e canal disponível, e relatórios operacionais simples." fill "#e2f0d9" {}
      sticky id "pilot-human" text "A equipa humana mantém todas as decisões e pode corrigir, suspender ou ignorar o apoio do sistema." fill "#d9ead3" {}
      sticky id "pilot-exclusions" text "Fora do âmbito: diagnóstico, triagem de urgência clínica, prescrições, priorização de pacientes por IA e decisões clínicas autónomas." fill "#f4cccc" {}
    ] id "pilot-section" name "Piloto inicial proposto" layout COLUMN fill "white" {}
    section [
      shape id "gate-auth" text "Autorização escrita?" kind DIAMOND fill "#fff2cc" {}
      sticky id "gate-auth-detail" text "Obter autorização escrita da unidade sanitária e das autoridades de saúde competentes. Sem acesso institucional, não iniciar." fill "#fff2cc" {}
      shape id "gate-workflow" text "Fluxo avaliado?" kind DIAMOND fill "#fff2cc" {}
      sticky id "gate-workflow-detail" text "Avaliar o fluxo de trabalho actual, responsabilidades, necessidades dos utilizadores e sistemas já existentes." fill "#fff2cc" {}
      shape id "gate-dhis2" text "Compatível com DHIS2?" kind DIAMOND fill "#fff2cc" {}
      sticky id "gate-dhis2-detail" text "Assegurar compatibilidade com o ecossistema nacional de informação sanitária DHIS2 de Angola. Integrar em vez de criar um sistema paralelo; se houver duplicação inviável, parar." fill "#fff2cc" {}
    ] id "gates-section" name "Dependências e portas críticas" layout GRID columns 2 fill "white" {}
    section [
      shape id "stage-consult" text "Consulta e linha de base" kind ROUNDED_RECTANGLE fill "#d9eaf7" {}
      shape id "stage-map" text "Mapear processos" kind ROUNDED_RECTANGLE fill "#d9eaf7" {}
      shape id "stage-review" text "Revisão legal e de segurança" kind ROUNDED_RECTANGLE fill "#d9eaf7" {}
      shape id "stage-prototype" text "Protótipo com dados mínimos" kind ROUNDED_RECTANGLE fill "#d9eaf7" {}
      shape id "stage-training" text "Formar a equipa" kind ROUNDED_RECTANGLE fill "#d9eaf7" {}
      shape id "stage-pilot" text "Piloto limitado" kind ROUNDED_RECTANGLE fill "#d9eaf7" {}
      shape id "stage-evaluation" text "Avaliação independente" kind ROUNDED_RECTANGLE fill "#d9eaf7" {}
      shape id "scale-decision" text "Evidência e aprovação?" kind DIAMOND fill "#fff2cc" {}
      shape id "stage-scale" text "Escala por fases" kind ROUNDED_RECTANGLE fill "#d9ead3" {}
      shape id "stage-stop" text "Rever ou parar" kind ROUNDED_RECTANGLE fill "#f4cccc" {}
    ] id "stages-section" name "Etapas de implementação" layout GRID columns 2 fill "white" {}
    section [
      sticky id "indicators-list" text "Medir: tempo de espera; faltas às marcações; erros de registo; tempo da equipa gasto em administração; satisfação dos utilizadores; disponibilidade do sistema; reclamações; incidentes de privacidade e segurança." fill "#e8eef7" {}
      sticky id "indicators-before" text "Antes: estabelecer a linha de base com definições, fontes e método documentados." fill "#d9eaf7" {}
      sticky id "indicators-after" text "Depois: repetir a medição com o mesmo método e comparar de forma transparente. Não preencher metas ou resultados antecipadamente." fill "#d9ead3" {}
    ] id "indicators-section" name "Indicadores antes e depois" layout COLUMN fill "white" {}
    section [
      sticky id "risk-access" text "Sem acesso institucional — não iniciar." fill "#f4cccc" {}
      sticky id "risk-data" text "Exposição de dados de saúde — minimizar dados, limitar por função, cifrar, definir retenção, preparar resposta a incidentes e realizar revisão legal." fill "#f4cccc" {}
      sticky id "risk-connectivity" text "Conectividade instável — manter alternativa offline ou de baixa largura de banda." fill "#fff2cc" {}
      sticky id "risk-resistance" text "Resistência da equipa — co-desenho, participação e formação prática." fill "#fff2cc" {}
      sticky id "risk-duplicate" text "Sistemas duplicados — integrar com o que existe ou parar." fill "#f4cccc" {}
      sticky id "risk-exclusion" text "Exclusão de pessoas sem telefone — manter atendimento presencial e opção em papel." fill "#fff2cc" {}
      sticky id "risk-lockin" text "Dependência de fornecedor e aumento de custos — normas abertas, portabilidade e plano de saída." fill "#fff2cc" {}
      sticky id "risk-ai" text "Erros de IA — manter a IA fora das decisões clínicas." fill "#f4cccc" {}
    ] id "risks-section" name "Riscos principais e mitigação" layout GRID columns 2 fill "white" {}
    section [
      sticky id "feasibility-value" text "Demonstrar valor público credível, alinhamento com políticas e originalidade face a iniciativas existentes." fill "#e8eef7" {}
      sticky id "feasibility-scope" text "Adoptar âmbito faseado, resultados mensuráveis e decisão de escala baseada em evidência." fill "#e8eef7" {}
      sticky id "feasibility-governance" text "Estabelecer governação multidisciplinar, financiamento transparente e auditoria independente." fill "#e8eef7" {}
      sticky id "feasibility-claims" text "Não alegar parceria, apoio ou aprovação da UNESCO, União Africana ou MINSA até existir acordo formal." fill "#fff2cc" {}
    ] id "feasibility-section" name "Condições de viabilidade da NEDA" layout GRID columns 2 fill "white" {}
    section [
      sticky id "later-principle" text "Fases posteriores, sujeitas à aprendizagem e à aprovação do piloto; não lançar simultaneamente." fill "#d9eaf7" {}
      sticky id "later-domains" text "Educação; conectividade; agricultura; ambiente; serviços públicos; telecomunicações." fill "#e8eef7" {}
    ] id "later-section" name "Outros domínios, mais tarde" layout COLUMN fill "white" {}
    section [
      sticky id "guard-human" text "Supervisão humana e responsabilização." fill "#d9ead3" {}
      sticky id "guard-rights" text "Direitos, acessibilidade e não exclusão." fill "#d9ead3" {}
      sticky id "guard-transparency" text "Transparência sobre finalidade, limites e decisões." fill "#d9ead3" {}
      sticky id "guard-data" text "Protecção de dados e minimização." fill "#d9ead3" {}
      sticky id "guard-security" text "Cibersegurança e resposta a incidentes." fill "#d9ead3" {}
      sticky id "guard-community" text "Participação comunitária e canais de reclamação." fill "#d9ead3" {}
    ] id "guardrails-section" name "Salvaguardas de governação" layout GRID columns 2 fill "white" {}
    connector id "mission-to-pilot" from "neda-goal" to "pilot-core" label "orienta o piloto" stroke "#4472c4" stroke-width THICK {}
    connector id "pilot-to-auth" from "pilot-core" to "gate-auth" label "exige autorização" stroke "#4472c4" stroke-width THICK {}
    connector id "auth-to-workflow" from "gate-auth" to "gate-workflow" label "depois, avaliar" stroke "#4472c4" {}
    connector id "workflow-to-dhis2" from "gate-workflow" to "gate-dhis2" label "confirmar integração" stroke "#4472c4" {}
    connector id "dhis2-to-consult" from "gate-dhis2" to "stage-consult" label "abre a preparação" stroke "#4472c4" stroke-width THICK {}
    connector id "stage-1-2" from "stage-consult" to "stage-map" label "seguinte" stroke "#5b9bd5" {}
    connector id "stage-2-3" from "stage-map" to "stage-review" label "seguinte" stroke "#5b9bd5" {}
    connector id "stage-3-4" from "stage-review" to "stage-prototype" label "se conforme" stroke "#5b9bd5" {}
    connector id "stage-4-5" from "stage-prototype" to "stage-training" label "preparar uso" stroke "#5b9bd5" {}
    connector id "stage-5-6" from "stage-training" to "stage-pilot" label "iniciar limitado" stroke "#5b9bd5" {}
    connector id "stage-6-7" from "stage-pilot" to "stage-evaluation" label "avaliar" stroke "#5b9bd5" {}
    connector id "stage-7-decision" from "stage-evaluation" to "scale-decision" label "apresenta evidência" stroke "#4472c4" stroke-width THICK {}
    connector id "decision-scale" from "scale-decision" to "stage-scale" label "sim, com aprovação" stroke "green" stroke-width THICK {}
    connector id "decision-stop" from "scale-decision" to "stage-stop" label "não" stroke "red" line-style DASHED {}
  ] id "neda-strategy" name "Estratégia de viabilidade e piloto" layout GRID columns 3 background "#f2f4f7" {}
] title "NEDA — Viabilidade e piloto inicial no Sumbe" show-page-tabs false show-page-menu false {}..

board [ page [
  shape id "client" text "Client" {}
  shape id "server" text "Server" {}
